"{
  "manifest_version": 3,
  "name": "WebScrapey AnyMD Sender",
  "version": "1.0.0",
  "description": "Send web serial links, selections, and titles directly to AnyMD with 1 click.",
  "permissions": [
    "contextMenus",
    "tabs"
  ],
  "background": {
    "service_worker": "background.js"
  },
  "action": {}
}
"

"chrome.runtime.onInstalled.addListener(() => {
  chrome.contextMenus.create({
    id: "send-page-to-anymd",
    title: "Send this Webnovel to AnyMD",
    contexts: ["page"]
  });
  chrome.contextMenus.create({
    id: "send-link-to-anymd",
    title: "Send Link to AnyMD as Webnovel",
    contexts: ["link"]
  });
});

chrome.contextMenus.onClicked.addListener(async (info, tab) => {
  if (info.menuItemId === "send-page-to-anymd") {
    await sendToAnyMD(tab.title, tab.url);
  } else if (info.menuItemId === "send-link-to-anymd") {
    await sendToAnyMD("Untitled Webnovel", info.linkUrl);
  }
});

chrome.action.onClicked.addListener(async (tab) => {
  await sendToAnyMD(tab.title, tab.url);
});

async function sendToAnyMD(title, url) {
  if (!url) return;
  // Clean up title (remove common site suffixes)
  let cleanTitle = title || "Untitled Webnovel";
  cleanTitle = cleanTitle
    .replace(/ - Royal Road$/i, "")
    .replace(/ - Scribble Hub$/i, "")
    .replace(/ \| Novel Updates$/i, "")
    .trim();

  const anymdBase = "https://meow.artkitty.net/lcmd/";
  const query = `?import_novel=${encodeURIComponent(cleanTitle)}&source=${encodeURIComponent(url)}&tags=status/to-acquire,webserial`;

  await chrome.tabs.create({ url: anymdBase + query });
}
